func run(argv []string) int {
    // Special help command handling mirrors go-flags style closely enough for public use.
    if len(argv) > 0 && argv[0] == "help" {
        if len(argv) == 1 { fmt.Print(helpText["help"]); return 0 }
        if strings.HasPrefix(argv[1], "-") { fmt.Print(helpText["help"]); return 0 }
        target := argv[1]
        if !commands[target] { logError(fmt.Sprintf("Unknown command %q", target)); return 2 }
        if target == "version" { fmt.Print(versionLine); return 0 }
        fmt.Print(helpText[target]); return 0
    }

    cli, helpReq, versionReq, parseRC := parseArgs(argv)
    if parseRC != 0 { return parseRC }
    if helpReq != nil {
        target := *helpReq
        if target == "" {
            if cli.cmd != "" && cli.cmd != "help" { target = cli.cmd } else { target = "help" }
        }
        if !commands[target] { logError(fmt.Sprintf("Unknown command %q", target)); return 78 }
        if target == "version" { fmt.Print(versionLine); return 0 }
        fmt.Print(helpText[target]); return 0
    }
    if versionReq { fmt.Print(versionLine); if cli.debug { logDebug("Exit code 0 (SUCCESS)") }; return 0 }
    if cli.cmd == "" { fmt.Print(helpText["help"]); return 0 }
    if !commands[cli.cmd] { logError(fmt.Sprintf("Unknown command %q", cli.cmd)); return 78 }
    if cli.promptPassword {
        fmt.Fprintln(os.Stderr, "Enter password: ")
        logError("STDIN must be a TTY to read password")
        if cli.cmd == "add-environment" {
            logError("If you are trying to supply a password value directly on the command-line, you must omit the space between the option flag and the value. For example, to use a password of \"asdf\", use either --password=asdf or -pasdf without any space before the value. This matches the password-handling behavior of the standard `mysql` client. For more information, see https://www.skeema.io/docs/options/#password")
        } else {
            logError("Interactive password prompting requires an input terminal. To supply a password non-interactively, configure the password value in a global option file, or supply it directly on the command-line, or set the $MYSQL_PWD environment variable. For more information, see https://www.skeema.io/docs/options/#password")
        }
        return 78
    }
    if cli.set["skip-my-cnf"] || (cli.set["my-cnf"] && cli.vals["my-cnf"]=="false") {
        logWarn("Option --my-cnf is deprecated. This option will be removed in Skeema v2, and .my.cnf will always be parsed, with additional safety logic already in place. For more information, visit https://www.skeema.io/v2-changes")
    }

    var rc int
    switch cli.cmd {
    case "version": rc = cmdVersion(cli)
    case "init": rc = cmdInit(cli)
    case "add-environment": rc = cmdAddEnv(cli)
    case "lint": rc = cmdLintFormat(cli, "lint")
    case "format": rc = cmdLintFormat(cli, "format")
    case "diff", "push": rc = cmdDiffPush(cli)
    case "pull": rc = cmdPull(cli)
    case "help": fmt.Print(helpText["help"]); rc = 0
    default: logError(fmt.Sprintf("Unknown command %q", cli.cmd)); rc = 78
    }
    if cli.debug {
        if rc == 0 { logDebug("Exit code 0 (SUCCESS)") } else { logDebug(fmt.Sprintf("Exit code %d", rc)) }
    }
    return rc
}

func parseArgs(argv []string) (CLI, *string, bool, int) {
    cli := CLI{vals: map[string]string{}, set: map[string]bool{}}
    var helpReq *string
    versionReq := false
    shortMap := map[byte]string{'o':"connect-options", 'H':"host-wrapper", 'u':"user", 'd':"dir", 'h':"host", 'P':"port", 'S':"socket", 't':"temp-schema", 'w':"workspace", 'x':"alter-wrapper", 'X':"ddl-wrapper"}
    for i:=0; i<len(argv); i++ {
        a := argv[i]
        if a == "--" { cli.args = append(cli.args, argv[i+1:]...); break }
        if strings.HasPrefix(a, "--") && len(a)>2 {
            raw := a[2:]
            name, val, hasEq := raw, "", false
            if idx:=strings.Index(raw,"="); idx>=0 { name=raw[:idx]; val=raw[idx+1:]; hasEq=true }
            if name == "help" {
                target := ""
                if hasEq { target = val } else if i+1 < len(argv) && !strings.HasPrefix(argv[i+1], "-") { target = argv[i+1]; i++ }
                helpReq = &target; continue
            }
            if name == "version" { versionReq = true; cli.set[name]=true; continue }
            norm := name
            if strings.HasPrefix(name,"skip-") { norm = name }
            if !valueOptions[norm] && !boolOptions[norm] { logError(fmt.Sprintf("CLI: Unknown option %q", name)); return cli,nil,false,78 }
            if valueOptions[norm] {
                if norm == "password" {
                    if hasEq { cli.vals[norm]=val; cli.set[norm]=true } else { cli.promptPassword = true; cli.set[norm]=true }
                    continue
                }
                if !hasEq {
                    if i+1 >= len(argv) { logError(fmt.Sprintf("CLI: Option %q requires a value", name)); return cli,nil,false,78 }
                    i++; val = argv[i]
                }
                cli.vals[norm]=val; cli.set[norm]=true
                if norm=="port" { cli.explicitPort=true }
                if norm=="host" { cli.hostCLI=true }
                if norm=="debug" { cli.debug=true }
            } else {
                cli.set[norm]=true
                if norm=="debug" { cli.debug=true }
                if norm=="skip-my-cnf" { cli.vals["my-cnf"]="false" }
            }
            continue
        }
        if strings.HasPrefix(a, "-") && len(a)>1 {
            c := a[1]
            rest := a[2:]
            if c == '?' {
                target := ""
                if rest != "" { target = rest } else if i+1 < len(argv) && !strings.HasPrefix(argv[i+1], "-") { target = argv[i+1]; i++ }
                helpReq = &target; continue
            }
            if c == 'p' {
                cli.set["password"] = true
                if rest != "" { cli.vals["password"] = rest } else { cli.promptPassword = true }
                continue
            }
            name, ok := shortMap[c]
            if !ok { logError(fmt.Sprintf("CLI: Unknown option %q", string(c))); return cli,nil,false,78 }
            // In the original, command-specific short flags are not accepted before the command.
            if cli.cmd == "" && (c=='h' || c=='d' || c=='P' || c=='S' || c=='t' || c=='w' || c=='x' || c=='X') {
                logError(fmt.Sprintf("CLI: Unknown option %q", string(c))); return cli,nil,false,78
            }
            val := rest
            if val == "" {
                if i+1 >= len(argv) { logError(fmt.Sprintf("CLI: Option %q requires a value", string(c))); return cli,nil,false,78 }
                i++; val = argv[i]
            }
            cli.vals[name]=val; cli.set[name]=true
            if name=="port" { cli.explicitPort=true }
            if name=="host" { cli.hostCLI=true }
            continue
        }
        if cli.cmd == "" && commands[a] { cli.cmd = a } else if cli.cmd == "" { cli.cmd = a } else { cli.args = append(cli.args, a) }
    }
    if cli.set["debug"] { cli.debug = true }
    return cli, helpReq, versionReq, 0
}

func cmdVersion(cli CLI) int {
    if len(cli.args) > 0 { logError(fmt.Sprintf("Extra command-line arg %q supplied; command version takes a max of 0 args", cli.args[0])); return 78 }
    fmt.Print(versionLine); return 0
}

func cmdInit(cli CLI) int {
    if len(cli.args) > 1 { logError(fmt.Sprintf("Extra command-line arg %q supplied; command init takes a max of 1 args", cli.args[1])); return 78 }
    if v,ok:=cli.vals["ssl-mode"]; ok && v!="" && v!="disabled" && v!="preferred" && v!="required" { logError("Invalid connection options: Option ssl-mode can only be set to one of these values: \"disabled\", \"preferred\", \"required\", \"\""); return 78 }
    host := cli.vals["host"]
    if host == "" { logError("Option --host must be supplied on the command-line"); return 78 }
    dir := cli.vals["dir"]
    if dir == "" { dir = host; if cli.explicitPort { dir = host+":"+defaultPort(cli.vals["port"]) } }
    abs, _ := filepath.Abs(dir)
    cfg := Config{Vals: map[string]string{"host":host, "port":defaultPort(cli.vals["port"]), "socket":defaultSocket(cli.vals["socket"] )}, Set: map[string]bool{"host":true}}
    if cli.explicitPort { cfg.Set["port"]=true }
    if cli.set["socket"] { cfg.Set["socket"]=true }
    addr, errtxt := connectionFailure(cfg)
    logError(fmt.Sprintf("Unable to connect to %s for %s: %s", addr, abs, errtxt))
    return 2
}

// Config is a very small INI-like representation of effective Skeema options.
type Config struct { Vals map[string]string; Set map[string]bool }
func (c Config) clone() Config { n:=Config{Vals:map[string]string{}, Set:map[string]bool{}}; for k,v:=range c.Vals{n.Vals[k]=v}; for k,v:=range c.Set{n.Set[k]=v}; return n }
func (c *Config) merge(o Config) { if c.Vals==nil { c.Vals=map[string]string{}; c.Set=map[string]bool{} }; for k,v:=range o.Vals { c.Vals[k]=v; c.Set[k]=true }; for k,v:=range o.Set { if !v { c.Set[k]=v } } }

func readConfig(path, env string) (Config, bool, error) {
    f, err := os.Open(path); if err != nil { if os.IsNotExist(err) { return Config{Vals:map[string]string{}, Set:map[string]bool{}}, false, nil }; return Config{}, false, err }
    defer f.Close()
    cfg := Config{Vals:map[string]string{}, Set:map[string]bool{}}
    section := ""
    scanner := bufio.NewScanner(f); lineNo:=0
    for scanner.Scan() { lineNo++; line:=strings.TrimSpace(scanner.Text()); if line=="" || strings.HasPrefix(line,"#") || strings.HasPrefix(line,";") { continue }
        if strings.HasPrefix(line,"[") { if !strings.Contains(line,"]") { return cfg,true,fmt.Errorf("Parse error in %s line %d: unterminated section name", path,lineNo) }; section=strings.TrimSpace(line[1:strings.Index(line,"]")]); continue }
        idx:=strings.Index(line,"=")
        if idx<0 { return cfg,true,fmt.Errorf("%s line %d: %s", path,lineNo, badOptionMsg(line)) }
        key:=strings.TrimSpace(line[:idx]); val:=strings.TrimSpace(line[idx+1:])
        if section=="" || section==env { cfg.Vals[key]=val; cfg.Set[key]=true }
    }
    return cfg, true, scanner.Err()
}

func badOptionMsg(line string) string { if !strings.Contains(line," ") { return fmt.Sprintf("Missing required value for option %s", line) }; return fmt.Sprintf("Unknown option %q", line) }

type fullConfig struct { top map[string]string; sections []section; names map[string]bool }
type section struct { name string; vals map[string]string }
func parseFullConfig(path string) (fullConfig, error) {
    fc:=fullConfig{top:map[string]string{}, names:map[string]bool{}}
    f,err:=os.Open(path); if err!=nil { return fc,err }; defer f.Close()
    var cur *section
    scanner:=bufio.NewScanner(f); lineNo:=0
    for scanner.Scan(){ lineNo++; line:=strings.TrimSpace(scanner.Text()); if line=="" || strings.HasPrefix(line,"#") || strings.HasPrefix(line,";") { continue }
        if strings.HasPrefix(line,"[") { if !strings.Contains(line,"]") { return fc,fmt.Errorf("Parse error in %s line %d: unterminated section name", path,lineNo) }; name:=strings.TrimSpace(line[1:strings.Index(line,"]")]); fc.sections=append(fc.sections, section{name:name, vals:map[string]string{}}); fc.names[name]=true; cur=&fc.sections[len(fc.sections)-1]; continue }
        idx:=strings.Index(line,"="); if idx<0 { return fc,fmt.Errorf("%s line %d: %s", path,lineNo,badOptionMsg(line)) }
        key:=strings.TrimSpace(line[:idx]); val:=strings.TrimSpace(line[idx+1:]); if cur==nil { fc.top[key]=val } else { cur.vals[key]=val }
    }
    return fc,scanner.Err()
}

func writeFullConfig(path string, fc fullConfig) error {
    var b strings.Builder
    writeMap := func(vals map[string]string){ keys:=make([]string,0,len(vals)); for k:=range vals{keys=append(keys,k)}; sort.Strings(keys); for _,k:=range keys{ b.WriteString(k+"="+vals[k]+"\n") } }
    writeMap(fc.top)
    for _,sec:= range fc.sections { if b.Len()>0 && !strings.HasSuffix(b.String(),"\n\n") { b.WriteString("\n") }; b.WriteString("["+sec.name+"]\n"); writeMap(sec.vals) }
    return os.WriteFile(path, []byte(b.String()), 0644)
}

func cmdAddEnv(cli CLI) int {
    if len(cli.args) < 1 { logError("Too few positional args supplied on command line; command add-environment requires at least 1 args"); return 78 }
    if len(cli.args) > 1 { logError(fmt.Sprintf("Extra command-line arg %q supplied; command add-environment takes a max of 1 args", cli.args[1])); return 78 }
    env := cli.args[0]
    dir := cli.vals["dir"]; if dir=="" { dir="." }
    st,err:=os.Stat(dir); if err!=nil || !st.IsDir() { logError("In add-environment, --dir must refer to a directory that already exists"); return 78 }
    absdir,_:=filepath.Abs(dir); path:=filepath.Join(absdir,".skeema")
    if _,err:=os.Stat(path); err!=nil { logError(fmt.Sprintf("Dir %s does not have an existing .skeema file! Can only use `skeema add-environment` on a dir previously created by `skeema init`", absdir)); return 78 }
    fc,err:=parseFullConfig(path); if err!=nil { logError(err.Error()); return 78 }
    if fc.names[env] { logError(fmt.Sprintf("Environment name %q already defined in %s", env,path)); return 78 }
    host:=cli.vals["host"]; if host=="" { logError("`skeema add-environment` requires --host to be supplied on command-line"); return 78 }
    if hw:=cli.vals["host-wrapper"]; hw!="" { c:=exec.Command("/bin/sh","-c",hw); c.Stdout=os.Stdout; c.Stderr=os.Stderr; if err:=c.Run(); err!=nil { if ee,ok:=err.(*exec.ExitError); ok { logError(err.Error()); return ee.ExitCode() }; logError(err.Error()); return 1 } }
    vals:=map[string]string{}
    for _,k:=range []string{"connect-options","ssl-mode","user"} { if cli.set[k] && cli.vals[k]!="" { vals[k]=cli.vals[k] } }
    vals["host"]=host
    port := defaultPort(cli.vals["port"])
    socket := defaultSocket(cli.vals["socket"])
    if host=="localhost" && !cli.explicitPort { vals["socket"]=socket } else { vals["port"]=port }
    fc.sections = append(fc.sections, section{name:env, vals:vals}); fc.names[env]=true
    if err:=writeFullConfig(path,fc); err!=nil { logError(err.Error()); return 1 }
    logWarn(fmt.Sprintf("Unable to automatically determine database server's vendor/version. To set manually, use the \"flavor\" option in %s", path))
    logInfo(fmt.Sprintf("Added environment [%s] to %s", env,path))
    return 0
}

func cmdLintFormat(cli CLI, kind string) int {
    if len(cli.args)>1 { logError(fmt.Sprintf("Extra command-line arg %q supplied; command %s takes a max of 1 args", cli.args[1], kind)); return 78 }
    if cli.hostCLI { logError("The host option cannot be set via command line for this command. For more information, visit https://www.skeema.io/docs/config/#limitations-on-host-and-schema-options"); return 78 }
    env:="production"; if len(cli.args)==1 { env=cli.args[0] }
    start,_:=filepath.Abs(".")
    errs:=0; dockerErr:=false
    var walk func(string, Config)
    walk = func(dir string, inherited Config) {
        base:=filepath.Base(dir); if strings.HasPrefix(base,".") && dir!=start { return }
        if kind=="lint" { logInfo("Linting "+dir) } else { logInfo("Reformatting "+dir) }
        eff:=inherited.clone(); if cfg,exists,err:=readConfig(filepath.Join(dir,".skeema"), env); err!=nil { logError(err.Error()); errs++; return } else if exists { eff.merge(cfg) }
        hasSQL:=dirHasSQL(dir); op := hasSQL || eff.Vals["schema"]!=""
        if op {
            msg, isDocker := operationProblem(eff, env, dir, kind)
            if msg!="" { errs++; if isDocker { dockerErr=true }; if kind=="lint" { logError(fmt.Sprintf("Skipping directory %s due to error: %s", relDisplay(start,dir), msg)) } else { logError(fmt.Sprintf("Skipping %s: %s", dir, msg)) }; return }
            return
        }
        entries,_:=os.ReadDir(dir); sort.Slice(entries,func(i,j int)bool{return entries[i].Name()<entries[j].Name()})
        for _,e:=range entries { if e.IsDir() { walk(filepath.Join(dir,e.Name()), eff) } }
    }
    walk(start, Config{Vals:map[string]string{}, Set:map[string]bool{}})
    if errs>0 && kind=="lint" { word:="operations"; if errs==1 { word="operation" }; logError(fmt.Sprintf("Skipped %d %s due to fatal errors", errs, word)) }
    if errs==0 { return 0 }
    if dockerErr { return 2 }
    return 78
}

func operationProblem(eff Config, env, dir, kind string) (string,bool) {
    workspace:=eff.Vals["workspace"]; if workspace=="" { workspace="temp-schema" }
    if workspace=="docker" {
        if _,err:=exec.LookPath("docker"); err!=nil { return "unable to find `docker` command-line client among directories in PATH", true }
        return "", false
    }
    host:=eff.Vals["host"]
    if host=="" { return fmt.Sprintf("This command needs either a host (with workspace=temp-schema) or flavor (with workspace=docker), but one is not configured for environment %q", env), false }
    addr, errtxt := connectionFailure(eff)
    return fmt.Sprintf("Unable to connect to %s for %s: %s", addr, dir, errtxt), false
}

func cmdDiffPush(cli CLI) int {
    cmd:=cli.cmd
    if len(cli.args)>1 { logError(fmt.Sprintf("Extra command-line arg %q supplied; command %s takes a max of 1 args", cli.args[1], cmd)); return 78 }
    if cli.hostCLI { logError("The host option cannot be set via command line for this command. For more information, visit https://www.skeema.io/docs/config/#limitations-on-host-and-schema-options"); return 78 }
    env:="production"; if len(cli.args)==1 { env=cli.args[0] }
    start,_:=filepath.Abs(".")
    errs:=0
    warnedNoHost:=false
    var walk func(string, Config) bool
    walk = func(dir string, inherited Config) bool {
        if strings.HasPrefix(filepath.Base(dir),".") && dir!=start { return false }
        eff:=inherited.clone(); if cfg,exists,err:=readConfig(filepath.Join(dir,".skeema"), env); err==nil && exists { eff.merge(cfg) }
        if eff.Vals["schema"]!="" {
            if eff.Vals["host"]=="" { logWarn(fmt.Sprintf("Skipping %s: no host defined for environment %q", dir, env)); logWarn(fmt.Sprintf("This command requires a hostname, which can be specified using the host option in a [%s] section of the .skeema file in this directory, or in a parent directory.", env)); warnedNoHost=true; return true }
            addr,errtxt:=connectionFailure(eff); logError(fmt.Sprintf("Skipping %s for %s: %s", addr, dir, errtxt)); errs++; return true
        }
        entries,_:=os.ReadDir(dir); sort.Slice(entries,func(i,j int)bool{return entries[i].Name()<entries[j].Name()})
        for _,e:=range entries { if e.IsDir() { if walk(filepath.Join(dir,e.Name()), eff) && errs>0 { return true } } }
        return false
    }
    walk(start, Config{Vals:map[string]string{}, Set:map[string]bool{}})
    _ = warnedNoHost
    if errs>0 { word:="problem"; if errs>1 { word="problems" }; logError(fmt.Sprintf("Skipped %d operation due to %s", errs, word)); return 2 }
    return 0
}

func cmdPull(cli CLI) int {
    if len(cli.args)>1 { logError(fmt.Sprintf("Extra command-line arg %q supplied; command pull takes a max of 1 args", cli.args[1])); return 78 }
    if cli.hostCLI { logError("The host option cannot be set via command line for this command. For more information, visit https://www.skeema.io/docs/config/#limitations-on-host-and-schema-options"); return 78 }
    if cli.debug { logDebug("Upgrade notice: the --format option, which currently defaults to true in Skeema v1, will change to default to false in Skeema v2. For more information, visit https://www.skeema.io/v2-changes") }
    env:="production"; if len(cli.args)==1 { env=cli.args[0] }
    start,_:=filepath.Abs(".")
    errs:=0
    var walk func(string, Config) bool
    walk = func(dir string, inherited Config) bool {
        if strings.HasPrefix(filepath.Base(dir),".") && dir!=start { return false }
        eff:=inherited.clone(); cfg,exists,err:=readConfig(filepath.Join(dir,".skeema"), env); if err!=nil { return false }; if exists { eff.merge(cfg) }
        if exists && (eff.Vals["host"]!="" || eff.Vals["schema"]!="") {
            if eff.Vals["host"]=="" { logWarn(fmt.Sprintf("Skipping %s: no host defined for environment %q", dir, env)); return true }
            addr,errtxt:=connectionFailure(eff); logWarn(fmt.Sprintf("Skipping %s: Unable to connect to %s for %s: %s", dir, addr, dir, errtxt)); errs++; return true
        }
        entries,_:=os.ReadDir(dir); sort.Slice(entries,func(i,j int)bool{return entries[i].Name()<entries[j].Name()})
        for _,e:=range entries { if e.IsDir() { walk(filepath.Join(dir,e.Name()), eff) } }
        return false
    }
    walk(start, Config{Vals:map[string]string{}, Set:map[string]bool{}})
    if errs>0 { return 1 }; return 0
}

func dirHasSQL(dir string) bool { entries,err:=os.ReadDir(dir); if err!=nil { return false }; for _,e:= range entries { if !e.IsDir() && strings.HasSuffix(strings.ToLower(e.Name()),".sql") { return true } }; return false }
func relDisplay(start, dir string) string { rel,err:=filepath.Rel(start,dir); if err!=nil || rel=="." { return filepath.Base(start) }; return filepath.Join(filepath.Base(start), rel) }
func defaultPort(p string) string { if p=="" { return "3306" }; return p }
func defaultSocket(s string) string { if s=="" { return "/tmp/mysql.sock" }; return s }

func connectionFailure(cfg Config) (string,string) {
    host:=cfg.Vals["host"]; if host=="" { host="localhost" }
    port:=defaultPort(cfg.Vals["port"]); socket:=defaultSocket(cfg.Vals["socket"])
    useSocket := host=="localhost" && !cfg.Set["port"]
    if useSocket {
        addr:=host+":"+socket
        _,err:=net.DialTimeout("unix", socket, 200*time.Millisecond)
        if err!=nil { return addr, err.Error() }
        return addr, errors.New("unexpected successful connection").Error()
    }
    addr:=host+":"+port
    _,err:=net.DialTimeout("tcp", addr, 500*time.Millisecond)
    if err!=nil { return addr, err.Error() }
    return addr, "unexpected successful connection"
}

func logMsg(level,msg string) { fmt.Fprintf(os.Stderr, "%s [%-5s] %s\n", time.Now().Format("2006-01-02 15:04:05"), level, msg) }
func logError(msg string) { logMsg("ERROR", msg) }
func logWarn(msg string) { logMsg("WARN", msg) }
func logInfo(msg string) { logMsg("INFO", msg) }
func logDebug(msg string) { logMsg("DEBUG", msg) }
