func run(argv []string) int {
    // Special help command handling mirrors go-flags style closely enough for public use.
    if len(argv) > 0 && argv[0] == "help" {
        if len(argv) == 1 { fmt.Print(helpText["help"]); return 0 }
        if strings.HasPrefix(argv[1], "-") { fmt.Print(helpText["help"]); return 0 }
        target := argv[1]
        if !commands[target] { logError(fmt.Sprintf("Unknown command %q", target)); return 2 }
        if target == "version" { fmt.Print(versionLine); return 0 }
        fmt.Print(helpText[target]); return 0
    }

    cli, helpReq, versionReq, parseRC := parseArgs(argv)
    if parseRC != 0 { return parseRC }
    if helpReq != nil {
        target := *helpReq
        if target == "" {
            if cli.cmd != "" && cli.cmd != "help" { target = cli.cmd } else { target = "help" }
        }
        if !commands[target] { logError(fmt.Sprintf("Unknown command %q", target)); return 78 }
        if target == "version" { fmt.Print(versionLine); return 0 }
        fmt.Print(helpText[target]); return 0
    }
    if versionReq { fmt.Print(versionLine); if cli.debug { logDebug("Exit code 0 (SUCCESS)") }; return 0 }
    if cli.cmd == "" { fmt.Print(helpText["help"]); return 0 }
    if !commands[cli.cmd] { logError(fmt.Sprintf("Unknown command %q", cli.cmd)); return 78 }
