        eff:=inherited.clone(); cfg,exists,err:=readConfig(filepath.Join(dir,".skeema"), env); if err!=nil { return false }; if exists { eff.merge(cfg) }
        if exists && (eff.Vals["host"]!="" || eff.Vals["schema"]!="") {
